36	export function getUserEmail(): string | null {
37	  const globalConfig = readGlobalConfig();
38	  return globalConfig?.account?.email || null;
39	}
40	
41	export function setUserEmail(email: string) {
42	  const globalConfig = readGlobalConfig();
43	  const account = globalConfig?.account ?? {};
44	  account.email = email;
45	  const config: Partial<GlobalConfig> = { account };
46	  writeGlobalConfigPartial(config);
47	}
