49	export function clearUserEmail() {
50	  const globalConfig = readGlobalConfig();
51	  const account = globalConfig?.account ?? {};
52	  delete account.email;
53	  const config: Partial<GlobalConfig> = { account };
54	  writeGlobalConfigPartial(config);
55	}
