57	export function getUserEmailNeedsValidation(): boolean {
58	  const globalConfig = readGlobalConfig();
59	  return globalConfig?.account?.emailNeedsValidation || false;
60	}
61	
62	export function setUserEmailNeedsValidation(needsValidation: boolean) {
63	  const globalConfig = readGlobalConfig();
64	  const account = globalConfig?.account ?? {};
65	  account.emailNeedsValidation = needsValidation;
66	  const config: Partial<GlobalConfig> = { account };
67	  writeGlobalConfigPartial(config);
68	}
