70	export function getUserEmailValidated(): boolean {
71	  const globalConfig = readGlobalConfig();
72	  return globalConfig?.account?.emailValidated || false;
73	}
74	
75	export function setUserEmailValidated(validated: boolean) {
76	  const globalConfig = readGlobalConfig();
77	  const account = globalConfig?.account ?? {};
78	  account.emailValidated = validated;
79	  const config: Partial<GlobalConfig> = { account };
80	  writeGlobalConfigPartial(config);
81	}
82	
83	export function getAuthor(): string | null {
84	  return getEnvString('PROMPTFOO_AUTHOR') || getUserEmail() || null;
85	}
86	
87	export function isLoggedIntoCloud(): boolean {
88	  // Check if user has authenticated with Promptfoo Cloud
89	  // This supports both interactive (email-based) and non-interactive (API key) authentication
90	  // CI environments can authenticate via API keys, so we no longer exclude CI
91	  const cloudConfig = new CloudConfig();
92	  return cloudConfig.isEnabled();
93	}
94	
95	/**
96	 * Get the authentication method used for cloud access
97	 * @returns 'api-key' | 'email' | 'none'
98	 */
99	export function getAuthMethod(): 'api-key' | 'email' | 'none' {
100	  const cloudConfig = new CloudConfig();
101	  const hasApiKey = cloudConfig.isEnabled();
102	  const hasEmail = !!getUserEmail();
103	
104	  if (hasApiKey && hasEmail) {
105	    // Both present - API key is the actual auth mechanism
106	    return 'api-key';
107	  }
108	  if (hasApiKey) {
109	    return 'api-key';
110	  }
111	  if (hasEmail) {
112	    // Email without API key - not fully authenticated
113	    // (this shouldn't happen in normal flow but handle it)
114	    return 'email';
115	  }
116	  return 'none';
117	}
