1	import { getEnvString } from '../envars';
2	import logger from '../logger';
3	import { readGlobalConfig, writeGlobalConfigPartial } from './globalConfig';
4	
5	export const CLOUD_API_HOST = 'https://api.promptfoo.app';
6	
7	export const API_HOST = getEnvString('API_HOST', CLOUD_API_HOST);
8	
9	// Free customers created before this date are grandfathered into auto-share.
10	export const SHARING_CUTOFF_DATE = new Date('2026-03-09T00:00:00Z');
11	
12	interface CloudUser {
13	  id: string;
14	  name: string;
15	  email: string;
16	  createdAt: Date;
17	  updatedAt: Date;
18	}
19	
20	interface CloudOrganization {
21	  id: string;
22	  name: string;
23	  createdAt: Date;
24	  updatedAt: Date;
25	}
26	
27	interface CloudTeam {
28	  id: string;
29	  name: string;
30	  slug: string;
31	  organizationId: string;
32	  createdAt: string;
33	  updatedAt: string;
34	}
35	
36	interface CloudApp {
37	  url: string;
38	}
39	
40	interface CloudTokenValidation {
41	  user: CloudUser;
42	  organization: CloudOrganization;
43	  app: CloudApp;
44	  hasActiveLicense?: boolean;
45	}
46	
47	export class CloudConfig {
48	  private config: {
49	    appUrl: string;
50	    apiHost?: string;
51	    apiKey?: string;
52	    sharing?: boolean;
53	    currentOrganizationId?: string;
54	    currentTeamId?: string;
55	    teams?: {
56	      [organizationId: string]: {
57	        currentTeamId?: string;
58	        cache?: Array<{
59	          id: string;
60	          name: string;
61	          slug: string;
62	          lastFetched: string;
63	        }>;
64	      };
65	    };
66	  };
67	
68	  constructor() {
69	    const savedConfig = readGlobalConfig()?.cloud || {};
70	    this.config = {
71	      appUrl: savedConfig.appUrl || 'https://www.promptfoo.app',
72	      apiHost: savedConfig.apiHost,
73	      apiKey: savedConfig.apiKey,
74	      sharing: savedConfig.sharing,
75	      currentOrganizationId: savedConfig.currentOrganizationId,
76	      currentTeamId: savedConfig.currentTeamId,
77	      teams: savedConfig.teams,
78	    };
79	  }
80	
81	  /**
82	   * Returns the API key from config file or PROMPTFOO_API_KEY environment variable.
83	   * Config file takes precedence over environment variable.
84	   */
85	  private resolveApiKey(): string | undefined {
86	    return this.config.apiKey || process.env.PROMPTFOO_API_KEY;
87	  }
88	
89	  /**
90	   * Returns the API host from config file, PROMPTFOO_CLOUD_API_URL environment variable,
91	   * or defaults to the standard cloud API host.
92	   * Config file takes precedence over environment variable.
93	   */
94	  private resolveApiHost(): string {
95	    return this.config.apiHost || process.env.PROMPTFOO_CLOUD_API_URL || API_HOST;
96	  }
97	
98	  isEnabled(): boolean {
99	    return !!this.resolveApiKey();
100	  }
101	
102	  setApiHost(apiHost: string): void {
103	    this.config.apiHost = apiHost;
104	    this.saveConfig();
105	  }
106	
107	  setApiKey(apiKey: string): void {
108	    this.config.apiKey = apiKey;
109	    this.saveConfig();
110	  }
111	
112	  getApiKey(): string | undefined {
113	    return this.resolveApiKey();
114	  }
115	
116	  getApiHost(): string {
117	    return this.resolveApiHost();
118	  }
119	
120	  setAppUrl(appUrl: string): void {
121	    this.config.appUrl = appUrl;
122	    this.saveConfig();
123	  }
124	
125	  getAppUrl(): string {
126	    return this.config.appUrl;
127	  }
128	
129	  getSharing(): boolean | undefined {
130	    return this.config.sharing;
131	  }
132	
133	  /**
134	   * Sets the sharing preference. Note: this value is only updated at authentication time
135	   * (via `validateAndSetApiToken`) and may become stale if the user's license status
136	   * changes between re-authentications.
137	   */
138	  setSharing(sharing: boolean): void {
139	    this.config.sharing = sharing;
140	    this.saveConfig();
141	  }
142	
143	  delete(): void {
144	    writeGlobalConfigPartial({ cloud: {} });
145	    this.reload();
146	  }
147	
148	  private saveConfig(): void {
149	    writeGlobalConfigPartial({ cloud: this.config });
150	    this.reload();
151	  }
152	
153	  private reload(): void {
154	    const savedConfig = readGlobalConfig()?.cloud || {};
155	    this.config = {
156	      appUrl: savedConfig.appUrl || 'https://www.promptfoo.app',
157	      apiHost: savedConfig.apiHost,
158	      apiKey: savedConfig.apiKey,
159	      sharing: savedConfig.sharing,
160	      currentOrganizationId: savedConfig.currentOrganizationId,
161	      currentTeamId: savedConfig.currentTeamId,
162	      teams: savedConfig.teams,
163	    };
164	  }
165	
166	  saveValidatedApiToken(
167	    token: string,
168	    apiHost: string,
169	    user: CloudUser,
170	    app: CloudApp,
171	    hasActiveLicense?: boolean,
172	  ): void {
173	    this.setApiKey(token);
174	    this.setApiHost(apiHost);
175	    this.setAppUrl(app.url);
176	    if (typeof hasActiveLicense === 'boolean') {
177	      const createdAt = user?.createdAt ? new Date(user.createdAt) : null;
178	      const isGrandfathered = createdAt != null && createdAt < SHARING_CUTOFF_DATE;
179	      this.setSharing(hasActiveLicense || isGrandfathered);
180	    }
181	  }
182	
183	  async validateApiToken(token: string, apiHost: string): Promise<CloudTokenValidation> {
184	    try {
185	      const { fetchWithProxy } = await import('../util/fetch');
186	      const response = await fetchWithProxy(`${apiHost}/api/v1/users/me`, {
187	        headers: {
188	          Authorization: `Bearer ${token}`,
189	        },
190	      });
191	
192	      if (!response.ok) {
193	        const errorMessage = await response.text();
194	        logger.error(
195	          `[Cloud] Failed to validate API token: ${errorMessage}. HTTP Status: ${response.status} - ${response.statusText}.`,
196	        );
197	        throw new Error('Failed to validate API token: ' + response.statusText);
198	      }
199	
200	      const { user, organization, app, hasActiveLicense } = await response.json();
201	
202	      return {
203	        user,
204	        organization,
205	        app,
206	        ...(typeof hasActiveLicense === 'boolean' ? { hasActiveLicense } : {}),
207	      };
208	    } catch (err) {
209	      const error = err as Error & { cause?: string };
210	      const errorMessage = error instanceof Error ? error.message : String(error);
211	      logger.error(`[Cloud] Failed to validate API token with host ${apiHost}: ${errorMessage}`);
212	      if (error.cause) {
213	        logger.error(`Cause: ${error.cause}`);
214	      }
215	      throw error;
216	    }
217	  }
218	
219	  async validateAndSetApiToken(
220	    token: string,
221	    apiHost: string,
222	  ): Promise<CloudTokenValidation & { hasActiveLicense: boolean }> {
223	    const { user, organization, app, hasActiveLicense } = await this.validateApiToken(
224	      token,
225	      apiHost,
226	    );
227	    this.saveValidatedApiToken(token, apiHost, user, app, hasActiveLicense);
228	
229	    return {
230	      user,
231	      organization,
232	      app,
233	      hasActiveLicense: typeof hasActiveLicense === 'boolean' ? hasActiveLicense : false,
234	    };
235	  }
236	
237	  getCurrentOrganizationId(): string | undefined {
238	    return this.config.currentOrganizationId;
239	  }
240	
241	  setCurrentOrganization(organizationId: string): void {
242	    this.config.currentOrganizationId = organizationId;
243	    this.saveConfig();
244	  }
245	
246	  getCurrentTeamId(organizationId?: string): string | undefined {
247	    if (organizationId) {
248	      return this.config.teams?.[organizationId]?.currentTeamId;
249	    }
250	    return this.config.currentTeamId;
251	  }
252	
253	  setCurrentTeamId(teamId: string, organizationId?: string): void {
254	    if (organizationId) {
255	      if (!this.config.teams) {
256	        this.config.teams = {};
257	      }
258	      if (!this.config.teams[organizationId]) {
259	        this.config.teams[organizationId] = {};
260	      }
261	      this.config.teams[organizationId].currentTeamId = teamId
