18	/**
19	 * Extract createdAt from export data, checking metadata and legacy locations.
20	 */
21	function extractCreatedAt(evalData: any): Date {
22	  // V3 exports store timestamp in metadata.evaluationCreatedAt
23	  if (evalData.metadata?.evaluationCreatedAt) {
24	    return new Date(evalData.metadata.evaluationCreatedAt);
25	  }
26	  // Also check results.timestamp as fallback
27	  if (evalData.results?.timestamp) {
28	    return new Date(evalData.results.timestamp);
29	  }
30	  // Legacy format may have createdAt at top level
31	  if (evalData.createdAt) {
32	    return new Date(evalData.createdAt);
33	  }
34	  // Default to now if no timestamp found
35	  return new Date();
36	}
