38	/**
39	 * Extract author from export data, checking metadata and legacy locations.
40	 */
41	function extractAuthor(evalData: any): string | undefined {
42	  // V3 exports store author in metadata.author
43	  if (evalData.metadata?.author) {
44	    return evalData.metadata.author;
45	  }
46	  // Legacy format may have author at top level
47	  return evalData.author;
