50	/**
51	 * Derive variable names from results for table display.
52	 */
53	function deriveVarsFromResults(results: any[]): string[] {
54	  const varSet = new Set<string>();
55	  for (const result of results) {
56	    if (result.vars && typeof result.vars === 'object') {
57	      for (const key of Object.keys(result.vars)) {
58	        varSet.add(key);
59	      }
60	    }
61	  }
62	  return Array.from(varSet);
63	}
